// Imagens originais geradas por código, exclusivamente para o banco descartável de QA.
import {createRequire} from "node:module";
const require=createRequire(new URL("../../package.json",import.meta.url));
const sharp=require("sharp");

export async function createSiteBuilderContent({storage,tenantId,workspaceId,create,apparel,content}){
 const upload=async(name,svg)=>{const body=await sharp(Buffer.from(svg)).png().toBuffer();return (await storage.put({key:`assets/${tenantId}/${workspaceId}/products/fixture-${name}.png`,body,contentType:"image/png"})).url;};
 const clothing=(background,color,kind="shirt")=>`<svg xmlns="http://www.w3.org/2000/svg" width="700" height="840" viewBox="0 0 700 840"><rect width="700" height="840" fill="${background}"/><ellipse cx="350" cy="727" rx="180" ry="24" fill="#000" opacity=".06"/><g transform="translate(112 140)">${kind==="shirt"?`<path d="M155 70L87 90 20 205 105 256 144 194 144 509Q235 535 332 509L332 194 372 256 456 205 390 90 321 70Q235 105 155 70Z" fill="${color}"/><path d="M192 78Q235 155 280 78" fill="none" stroke="#fff" stroke-width="9" opacity=".6"/><path d="M154 480Q235 500 323 480M42 204L99 239M378 239L433 205" fill="none" stroke="#fff" stroke-width="3" opacity=".3"/>`:`<path d="M128 55H346L372 520 262 530 237 245 215 530 104 520Z" fill="${color}"/><path d="M129 85H345M237 89V245" fill="none" stroke="#fff" stroke-width="4" opacity=".4"/><path d="M144 96Q140 165 202 155M328 96Q332 165 272 155" fill="none" stroke="#fff" stroke-width="3" opacity=".3"/>`}</g></svg>`;
 const hero=await upload("hero",`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="1040" viewBox="0 0 1200 1040"><rect width="1200" height="1040" fill="#e6ddcc"/><path d="M240 1040V470a360 360 0 0 1 720 0v570" fill="#d3c4a9"/><circle cx="925" cy="238" r="116" fill="#f4ede0"/><path d="M1040 1000Q970 770 1080 620M1050 890Q930 800 945 735M1062 805Q1185 730 1160 670" fill="none" stroke="#6f8066" stroke-width="18" stroke-linecap="round"/><path d="M335 1040L353 498Q595 330 855 498L878 1040" fill="#f4ead6"/><path d="M530 443L585 365 645 443 672 556 610 613 545 558Z" fill="#b48560"/><path d="M450 469L360 500 280 793 390 831 472 653M733 469L835 500 913 793 798 831 716 653" fill="#c87c5b"/><path d="M451 469Q585 526 734 469L754 925Q600 960 430 925Z" fill="#c87c5b"/><path d="M540 480Q590 568 649 480" fill="none" stroke="#e9b49a" stroke-width="13"/><path d="M456 700H724M456 727H724M456 754H724" stroke="#e8ae8a" stroke-width="4" opacity=".65"/><path d="M430 925L425 1040H572L596 950 617 1040H762L754 925" fill="#7a876e"/><rect x="144" y="727" width="160" height="190" rx="80" fill="#d1aa85"/><path d="M164 800Q220 700 265 795" fill="none" stroke="#6c765e" stroke-width="7"/></svg>`);
 const mobile=await upload("hero-mobile",`<svg xmlns="http://www.w3.org/2000/svg" width="600" height="760"><rect width="600" height="760" fill="#e6ddcc"/><path d="M55 760V300a245 245 0 0 1 490 0v460" fill="#d3c4a9"/><circle cx="451" cy="154" r="73" fill="#f4ede0"/><path d="M201 245L130 278 64 425 153 470 190 410 180 668Q300 693 420 668L410 410 447 470 536 425 470 278 399 245Q300 283 201 245Z" fill="#c87c5b"/><path d="M253 259Q300 344 347 259" fill="none" stroke="#e9b49a" stroke-width="12"/></svg>`);
 const imageUrls=await Promise.all([upload("shirt",clothing("#ede9e0","#73846b")),upload("cream",clothing("#e7e9e2","#e2cba5")),upload("rose",clothing("#efe3db","#bf7c69")),upload("pants",clothing("#e7e9e2","#858e78","pants"))]);
 const products=[];
 for(const [index,name] of ["Camiseta areia — exemplo","Camiseta terracota — exemplo","Calça oliva — exemplo"].entries())products.push(await create({name,priceCents:9900+index*2000,imageUrls:[imageUrls[index+1]],details:{...apparel.details,slug:`modelo-exemplo-${index}`,options:[],apparel:{material:"Algodão",collection:"Catálogo de demonstração"}}}));
 return {apparelImage:imageUrls[0],content:{...content,description:"Design simples. Texturas naturais. Uma seleção para os pequenos momentos.",header:{showSearch:true,sticky:true,navigation:[{id:"home",label:"Início",url:"/",enabled:true,newTab:false},{id:"catalog",label:"Coleção",url:"#catalogo",enabled:true,newTab:false},{id:"about",label:"Nossa história",url:"/sobre",enabled:true,newTab:false},{id:"contact",label:"Contato",url:"#contato",enabled:true,newTab:false}],announcement:{enabled:true,text:"SITE DE DEMONSTRAÇÃO · Dados e imagens de teste"}},footer:"Uma marca fictícia para experimentar as possibilidades do seu site.",footerNote:"Demonstração local · Nenhuma compra real.",blocks:[{id:"hero",type:"hero",enabled:true,eyebrow:"PEQUENOS DETALHES. BOAS ESCOLHAS.",title:"Feito para viver bons momentos.",text:"Cores que acolhem, formas que inspiram. Descubra um jeito leve de apresentar a sua marca.",imageUrl:hero,imageAlt:"Ilustração original de roupas em tons naturais",buttonLabel:"Conheça a coleção",buttonUrl:"#catalogo",slides:[{id:"first",title:"Feito para viver bons momentos.",text:"Cores que acolhem, formas que inspiram. Descubra um jeito leve de apresentar a sua marca.",imageUrl:hero,mobileImageUrl:mobile,imageAlt:"Roupas ilustradas em tons naturais",buttonLabel:"Conheça a coleção",buttonUrl:"#catalogo",enabled:true}]},{id:"features",type:"features",enabled:true,title:"Escolhas com significado",items:[{title:"Seu estilo",text:"Cada detalhe com a personalidade da sua marca.",icon:"sparkles"},{title:"Mais cuidado",text:"Uma apresentação que valoriza seus produtos.",icon:"heart"},{title:"Perto de você",text:"Converse diretamente com nossa equipe.",icon:"pin"}]},{id:"catalog",type:"catalog",enabled:true,title:"Nosso catálogo",eyebrow:"UMA SELEÇÃO ESPECIAL",text:"Encontre o que combina com o seu momento.",productIds:[apparel.id,...products.map(product=>product.id)]},{id:"story",type:"image_text",enabled:true,title:"Uma história que merece ser contada.",eyebrow:"NOSSA ESSÊNCIA",text:"Seu site pode ir além de uma vitrine. Apresente sua história, seus valores e o cuidado por trás de cada escolha.",imageUrl:mobile,imageAlt:"Ilustração de camiseta terracota",buttonLabel:"Conheça nossa história",buttonUrl:"/sobre",style:{imagePosition:"left"}},{id:"contact",type:"contact",enabled:true,title:"Vamos conversar?",text:"Nossa equipe está aqui para ajudar você a encontrar o que procura."}]}};
}
